css:
body {
    font-family: Arial, sans-serif;
    margin: 40px;
    line-height: 1.6;
}


#table {
   font-family: Arial, Helvetica, sans-serif;
   border-collapse: collapse;
   width: 100%;

}

#table td, #table th {
  border: 1px solid #bfbdbd;
  padding: 2px;
  padding-top: 2px;
  padding-bottom: 2px;
}

#table tr:nth-child(even){background-color: #f2f2f2;}

#table tr:hover {background-color: #ddd;}

#table th {
  padding-top: 2px;
  padding-bottom: 2px;
  text-align: left;
  background-color: #dce4e6;
  color: white;
}




.header {
    text-align: center;
}
.content {
    margin-top: -30px;
}
.content p {
    margin: 5px 0;
}
.signature {
    margin-top: 40px;
}
.signature p {
    margin: 0;
}
.signature img {
    width: 100px;
    height: auto;
}
